var opponentReportKey=null,opponentMatchContext=null;
function oppositionSetPieceMarkup(d){if(!d)return '';const text=matchdayText;return '<details class="opposition-set-pieces"><summary>세트피스 분석 · 키커와 공중볼 비교</summary><p>'+text(d.note)+'</p><div class="opposition-deadball-grid">'+d.roles.map(r=>'<article><h3>'+text(r.label)+'</h3><p>우리 현재 담당 <b>'+text(r.ours?.name||'출전 선수 없음')+'</b>'+(r.ours?' · 지표 '+r.ours.score:'')+'</p><ol aria-label="상대 '+text(r.label)+' 지표 후보">'+r.opponentCandidates.map(p=>'<li><span>'+text(p.name)+' <small>'+p.pos+'</small></span><b>'+p.score+'</b></li>').join('')+'</ol></article>').join('')+'</div><dl class="opposition-deadball-xg">'+d.chances.map(c=>'<div><dt>'+c.label+'당 xG</dt><dd>'+(c.ours===null?'—':c.ours.toFixed(3))+' : '+c.opponent.toFixed(3)+' <small>우리 / 상대</small></dd></div>').join('')+'</dl><small>프리킥 담당을 바꾸려면 경기 준비의 전술 창에서 지정하세요. 교체·퇴장 시 현재 필드의 대체 담당을 표시합니다.</small></details>';}
function renderOpponentReport(){
 const host=document.getElementById('opposition-report');if(!host||host.hidden||view!=='match'||!state)return;
 const key=[season.year,season.round,season.competition,state.seed,state.phase,state.minute,state.formation,state.tactic,JSON.stringify(state.setPieces),JSON.stringify(state.discipline?.events),state.lineup.map(id=>id+':'+state.players[id].energy).join(',')].join('|');if(key===opponentReportKey)return;
 const d=Opposition.read(season);if(!d.valid){host.innerHTML='';return;}opponentReportKey=key;
 const deadballOpen=!!host.querySelector?.('.opposition-set-pieces')?.open,coachOpen=!!host.querySelector?.('.opposition-coach-analysis')?.open;const text=matchdayText,n=n=>Math.round(n),plan=typeof TacticsBoard!=='undefined'?TacticsBoard.read(season):null,keyPlayer=d.keyPlayer,keyRow=keyPlayer&&d.lineup.find(p=>p.id===keyPlayer.id);
 const keyPlayerMarkup=keyPlayer?'<article class="opposition-key-player" aria-label="요주의 선수 '+text(keyPlayer.name)+'"><div class="opposition-key-marker" aria-hidden="true"><span>'+text(keyRow?.no||'★')+'</span><small>KEY</small></div><div class="opposition-key-copy"><div><span>요주의 선수</span><b>'+text(keyPlayer.role)+'</b></div><h3>'+text(keyPlayer.name)+'</h3><p>'+text(keyPlayer.pos)+' · 종합 '+n(keyPlayer.overall)+' · '+text(keyPlayer.threat)+'</p></div><span class="opposition-key-focus">상대 전술의 중심</span></article>':'';
 const discipline=d.rivalDiscipline||{rows:[],absent:[],applicable:false,label:'리그'},disciplineLabel=text(discipline.label||'리그'),disciplineMatch=disciplineLabel==='리그'?'리그전':disciplineLabel+' 경기',disciplineMarkup=discipline.rows.length?'<div class="opposition-discipline"><b>'+disciplineLabel+' 경고·출전 정지</b><span>'+discipline.rows.map(row=>text(row.name)+' · '+(row.pending?(discipline.applicable?'이번 '+disciplineMatch+' 결장':'다음 '+disciplineMatch+' 정지 대기')+' · ':'')+(row.yellows?'경고 '+row.yellows+'/3':'퇴장 정지')).join('　·　')+'</span></div>':'';
 const reference=d.club.reference?'<span>실제 구단 전력 참고 <b>'+text(typeof EnglishPyramid!=='undefined'?EnglishPyramid.koreanName(d.club.reference):d.club.reference)+'</b></span>':'<span>구단 전력 <b>창작 팀 기준</b></span>';
 const liveMode=state.phase!=='prep'&&state.version>=9?Football.opponentPlan(state):null,livePlan=liveMode?'<span>상대 감독의 현재 지시 <b>'+text(Football.opponentPlanLabels[liveMode])+'</b></span>':'';
 const active=d.lineup.filter(p=>!p.dismissed),overall=active.length?n(active.reduce((sum,p)=>sum+p.overall,0)/active.length):null,energy=active.length?n(active.reduce((sum,p)=>sum+p.energy,0)/active.length):null;
 const summary='<dl class="opposition-snapshot" aria-label="상대 핵심 정보"><div><dt>포메이션</dt><dd>'+text(d.plan.formation.split('').join('–'))+'</dd></div><div><dt>'+(liveMode?'현재 지시':'전술 성향')+'</dt><dd>'+text(liveMode?Football.opponentPlanLabels[liveMode]:d.plan.label)+'</dd></div><div><dt>활동 선수 종합·계산</dt><dd>'+(overall??'—')+'</dd></div><div><dt>활동 선수 평균 체력</dt><dd>'+(energy??'—')+'</dd></div></dl>';
 const rows=d.lineup.map(p=>{const featured=keyPlayer?.id===p.id,cardId=p.replacementFor?'opp'+(p.no-1):p.id,card=typeof matchdayCardInfo==='function'?matchdayCardInfo(cardId,1):{markup:''},classes=[p.dismissed?'opposition-dismissed':'',featured?'opposition-key-row':'',p.replacementFor?'opposition-reserve-row':''].filter(Boolean).join(' ');return '<tr'+(classes?' class="'+classes+'"':'')+'><td><button type="button" class="opposition-player-button" data-opponent-player="'+text(p.identity)+'" aria-label="'+text(p.name)+' 상대 선수 상세"><i>'+p.no+'</i>'+Portraits.html(p)+'<span class="opposition-player-name">'+text(p.name)+(featured?'<em class="opposition-key-badge">요주의</em>':'')+'<small>'+text(p.pos)+' · '+text(p.primaryLabel)+'<span class="opposition-mobile-attributes"> '+p.primary+' · 지구력 '+p.endurance+'</span></small>'+(p.replacementFor?'<small class="opposition-reserve-note">'+text(p.replacementFor)+' · '+text(p.replacementReason||'누적 정지')+' · 후보 출전</small>':'')+card.markup+'</span></button></td><td><b class="opposition-overall">'+p.overall+'</b></td><td class="opposition-primary">'+p.primary+'</td><td>'+p.speed+'</td><td class="opposition-endurance">'+p.endurance+'</td><td><b class="opposition-energy '+(p.energy<50?'loss':'')+'">'+n(p.energy)+'</b><small>'+(p.dismissed?'퇴장':text(p.condition))+'</small></td></tr>';}).join('');
 const coach='<details class="opposition-coach-analysis"><summary>코치 분석 · 전력 비교와 요주의 선수</summary>'+keyPlayerMarkup+'<div class="opposition-comparisons">'+d.comparisons.map(r=>'<div><span>'+text(r.label)+'</span><b>'+n(r.ours)+' <i>:</i> '+n(r.opponent)+'</b><small>우리 / 상대</small></div>').join('')+'</div><p class="opposition-advice">'+text(d.advice)+(plan?.valid?' <strong>코치 제안: '+text(plan.recommendation.label)+'</strong>':'')+'</p><div class="opposition-condition"><span>활동 인원 <b>'+d.activePlayers.ours+' : '+d.activePlayers.opponent+'</b></span><span>우리 평균 체력 <b>'+n(d.condition.ours)+'</b></span><span>우리 체력 주의 <b>'+d.condition.tired+'명</b></span></div><div class="opposition-plan">'+livePlan+reference+'<span>리그 최근 경기 <b>'+text(d.recent.join(' · ')||'기록 없음')+'</b></span></div></details>';
 host.innerHTML='<section class="opposition-card"><header><div><span class="eyebrow">상대 팀 / '+(state.phase==='prep'?'킥오프 전':'경기 중')+'</span><h2>'+text(d.club.name)+'</h2></div><span class="opposition-crest" style="background:'+d.club.color+'">'+text(d.club.code)+'</span></header>'+summary+'<div class="opposition-roster-heading"><h3>'+(state.phase==='prep'?'상대 예상 선발':'상대 선발')+' 11명</h3><span>종합·속도·체력</span></div><table class="opposition-roster"><thead><tr><th>선수 / 포지션</th><th><abbr title="포지션 주요 능력을 가중한 1~99 종합 지수">종합</abbr></th><th class="opposition-primary">주능력</th><th>속도</th><th class="opposition-endurance">지구력</th><th>체력</th></tr></thead><tbody>'+rows+'</tbody></table>'+disciplineMarkup+coach+oppositionSetPieceMarkup(d.setPieces)+'<p class="opposition-note">'+(season.suspensions?'우리 구단은 대회별 경고 3회·퇴장 시 대회별 정지를 적용합니다.':'우리 구단은 카드 누적 정지를 홈의 출전 정지 규칙에서 적용합니다.')+' 상대 구단은 같은 대회에서 경고 3회 누적·퇴장 시 다음 해당 대회 경기에 정지를 적용합니다. 종합 능력은 포지션별 창작 가중치이며 실제 선수 평점이나 실시간 데이터가 아닙니다. 전술 지시에서 운영을 바꾸거나 전술 분석에서 비교하세요.</p></section>';
 const deadball=host.querySelector?.('.opposition-set-pieces');if(deadball)deadball.open=deadballOpen;const coachDetails=host.querySelector?.('.opposition-coach-analysis');if(coachDetails)coachDetails.open=coachOpen;
}
